// Import of required libraries
import { test, expect, SkyrampClient, checkSchema, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, updateLink, getLinksFavorites, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const take = "2";
    const take_1 = "101";

    const collectionsPostResponse = await createCollection(client, headers, "tb-favorites-col", "", "#0ea5e9");

    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-favorites-col");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.isPublic"), 'isPublic').toBe(false);
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.ownerId"), 'ownerId').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(checkSchema(collectionsPostResponse, `{"response":{"parentId":null}}`), 'parentId is present and null').toBe(true);

    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    const ownerId = getResponseValue(collectionsPostResponse, "response.ownerId");

    const [linksPostResponse, linksPost1Response, linksPost2Response] = await Promise.all([
        createLink(client, headers, collectionId, "tb-fav-a", "https://example.com/tb-fav-a"),
        createLink(client, headers, collectionId, "tb-fav-b", "https://example.com/tb-fav-b"),
        createLink(client, headers, collectionId, "tb-fav-c", "https://example.com/tb-fav-c"),
    ]);

    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(linksPost1Response.statusCode, 'status code').toBe(200);
    expect(linksPost2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("tb-fav-a");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/tb-fav-a");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(collectionId);
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(linksPost1Response, "response.name"), 'name').toBe("tb-fav-b");
    expect(getResponseValue(linksPost1Response, "response.url"), 'url').toBe("https://example.com/tb-fav-b");
    expect(getResponseValue(linksPost1Response, "response.collectionId"), 'collectionId').toBe(collectionId);
    expect(getResponseValue(linksPost2Response, "response.name"), 'name').toBe("tb-fav-c");
    expect(getResponseValue(linksPost2Response, "response.url"), 'url').toBe("https://example.com/tb-fav-c");
    expect(getResponseValue(linksPost2Response, "response.collectionId"), 'collectionId').toBe(collectionId);

    const linkAId = getResponseValue(linksPostResponse, "response.id");
    const linkBId = getResponseValue(linksPost1Response, "response.id");
    const linkCId = getResponseValue(linksPost2Response, "response.id");

    const [linksLinksPutResponse, linksLinksPut1Response, linksLinksPut2Response] = await Promise.all([
        updateLink(client, headers, linkAId, collectionId, ownerId, ownerId, "tb-fav-a", "https://example.com/tb-fav-a"),
        updateLink(client, headers, linkBId, collectionId, ownerId, ownerId, "tb-fav-b", "https://example.com/tb-fav-b"),
        updateLink(client, headers, linkCId, collectionId, ownerId, ownerId, "tb-fav-c", "https://example.com/tb-fav-c"),
    ]);

    expect(linksLinksPutResponse.statusCode, 'status code').toBe(200);
    expect(linksLinksPut1Response.statusCode, 'status code').toBe(200);
    expect(linksLinksPut2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksPutResponse, "response.id"), 'id').toBe(linkAId);
    expect(getResponseValue(linksLinksPutResponse, "response.pinnedBy.0.id"), 'link A is pinned by the caller').toBe(ownerId);
    expect(getResponseValue(linksLinksPut1Response, "response.id"), 'id').toBe(linkBId);
    expect(getResponseValue(linksLinksPut1Response, "response.pinnedBy.0.id"), 'link B is pinned by the caller').toBe(ownerId);
    expect(getResponseValue(linksLinksPut2Response, "response.id"), 'id').toBe(linkCId);
    expect(getResponseValue(linksLinksPut2Response, "response.pinnedBy.0.id"), 'link C is pinned by the caller').toBe(ownerId);
    expect(getResponseValue(linksLinksPutResponse, "response.pinnedBy.1"), 'only the caller pins link A').toBeNull();
    expect(getResponseValue(linksLinksPut1Response, "response.pinnedBy.1"), 'only the caller pins link B').toBeNull();
    expect(getResponseValue(linksLinksPut2Response, "response.pinnedBy.1"), 'only the caller pins link C').toBeNull();

    const favoritesGetResponse = await getLinksFavorites(client, headers, {"take": [take_1]});

    expect(favoritesGetResponse.statusCode, 'status code').toBe(200);

    const allFavorites = getResponseValue(favoritesGetResponse, "response.links");
    expect(allFavorites.length, 'the three pinned links are the caller\'s favorites').toBe(3);
    expect(allFavorites.map((link: any) => link.id), 'link A is a favorite').toContain(linkAId);
    expect(allFavorites.map((link: any) => link.id), 'link B is a favorite').toContain(linkBId);
    expect(allFavorites.map((link: any) => link.id), 'link C is a favorite').toContain(linkCId);
    expect(allFavorites.every((link: any) => link.collectionId === collectionId), 'every favorite belongs to the created collection').toBe(true);
    expect(allFavorites.every((link: any) => link.pinnedBy.some((pin: any) => pin.id === ownerId)), 'every favorite carries pinnedBy for the caller').toBe(true);
    expect(Date.parse(allFavorites[0].createdAt), 'favorites are ordered newest first').toBeGreaterThanOrEqual(Date.parse(allFavorites[1].createdAt));
    expect(Date.parse(allFavorites[1].createdAt), 'favorites are ordered newest first').toBeGreaterThanOrEqual(Date.parse(allFavorites[2].createdAt));
    expect(allFavorites[3], 'no fourth favorite').toBeUndefined();
    expect(getResponseValue(favoritesGetResponse, "response.cursor"), 'a page shorter than take carries no cursor').toBeNull();

    const favoritesGet1Response = await getLinksFavorites(client, headers, {"take": [take]});

    expect(favoritesGet1Response.statusCode, 'status code').toBe(200);

    const page1Favorites = getResponseValue(favoritesGet1Response, "response.links");
    expect(page1Favorites.length, 'take=2 bounds the page to two links').toBe(2);
    expect(page1Favorites[0].id, 'page one starts with the newest favorite').toBe(allFavorites[0].id);
    expect(page1Favorites[1].id, 'page one continues with the second newest favorite').toBe(allFavorites[1].id);
    expect(getResponseValue(favoritesGet1Response, "response.cursor"), 'the cursor is the id of the last link on the page').toBe(String(page1Favorites[1].id));

    const favoritesGet2Response = await getLinksFavorites(client, headers, {
        "cursor": [getResponseValue(favoritesGet1Response, "response.cursor")],
        "take": [take]
    });

    expect(favoritesGet2Response.statusCode, 'status code').toBe(200);

    const page2Favorites = getResponseValue(favoritesGet2Response, "response.links");
    expect(page2Favorites.length, 'page two holds the remaining favorite').toBe(1);
    expect(page2Favorites[0].id, 'page two continues after the cursor').toBe(allFavorites[2].id);
    expect(page1Favorites.map((link: any) => link.id).includes(page2Favorites[0].id), 'page two repeats no link from page one').toBe(false);
    expect(getResponseValue(favoritesGet2Response, "response.cursor"), 'the last page carries no cursor').toBeNull();

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, headers, collectionId);

    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'the created collection is deleted').toBe(collectionId);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.name"), 'name').toBe("tb-favorites-col");
});
